"""Tests for notifications generated by followed speaker activity."""

from datetime import timedelta

from django.contrib.auth import get_user_model
from django.test import TestCase
from django.utils import timezone
from rest_framework.reverse import reverse
from rest_framework.test import APIClient

from events.models import Event
from profiles.models.speaker_models import (
    Notification,
    SpeakerExperiences,
    SpeakerFollow,
    SpeakerProfile,
)
from talks.choices import TalkCategoryChoices
from talks.models import Talks


class SpeakerActivityNotificationTests(TestCase):
    """Verify relevant activity reaches followers without notifying other users."""

    def setUp(self):
        """Create a speaker, a follower, and an unrelated account."""
        user_model = get_user_model()
        self.speaker_user = user_model.objects.create_user(
            username="followed_speaker",
            email="speaker@example.com",
            password="test-password",
        )
        self.follower = user_model.objects.create_user(
            username="speaker_follower",
            email="follower@example.com",
            password="test-password",
        )
        self.other_user = user_model.objects.create_user(
            username="other_user",
            email="other@example.com",
            password="test-password",
        )
        self.speaker = SpeakerProfile.objects.create(
            user_account=self.speaker_user,
            organization="Example",
        )
        self.other_speaker = SpeakerProfile.objects.create(
            user_account=self.other_user,
            organization="Other",
        )
        SpeakerFollow.objects.create(follower=self.follower, speaker=self.speaker)

    def test_new_experience_notifies_followers_with_profile_link(self):
        """Adding an experience notifies only followers and links to the profile."""
        with self.captureOnCommitCallbacks(execute=True):
            experience = SpeakerExperiences.objects.create(
                speaker=self.speaker,
                event_name="Developer Summit",
                event_date=timezone.localdate(),
                topic="Reliable APIs",
            )

        notification = Notification.objects.get(user=self.follower)
        self.assertIn("Reliable APIs", notification.message)
        self.assertEqual(notification.link, f"/speakers/{self.speaker.slug}")
        self.assertFalse(notification.is_read)
        self.assertFalse(Notification.objects.filter(user=self.speaker_user).exists())
        self.assertFalse(Notification.objects.filter(user=self.other_user).exists())

        with self.captureOnCommitCallbacks(execute=True):
            experience.topic = "Reliable API design"
            experience.save()
        self.assertEqual(Notification.objects.filter(user=self.follower).count(), 1)

    def test_adding_speaker_to_upcoming_active_event_notifies_followers(self):
        """A public upcoming event creates a relevant event-linked notification."""
        event = Event.objects.create(
            title="Future Conference",
            website="https://example.com/future-conference",
            is_active=True,
            start_date_time=timezone.now() + timedelta(days=20),
        )

        with self.captureOnCommitCallbacks(execute=True):
            self.speaker.events_spoken.add(event)

        notification = Notification.objects.get(user=self.follower)
        self.assertIn(event.title, notification.message)
        self.assertEqual(notification.link, event.get_absolute_url())

    def test_reverse_event_speaker_assignment_notifies_followers(self):
        """Adding a speaker from the event side uses the same notification flow."""
        event = Event.objects.create(
            title="Reverse Assignment Conference",
            website="https://example.com/reverse-assignment",
            is_active=True,
            start_date_time=timezone.now() + timedelta(days=20),
        )

        with self.captureOnCommitCallbacks(execute=True):
            event.speakers.add(self.speaker)

        notification = Notification.objects.get(user=self.follower)
        self.assertIn(event.title, notification.message)
        self.assertEqual(notification.link, event.get_absolute_url())

    def test_past_or_unpublished_events_do_not_notify_followers(self):
        """Only active events in the future trigger follower updates."""
        past_event = Event.objects.create(
            title="Past Conference",
            website="https://example.com/past-conference",
            is_active=True,
            start_date_time=timezone.now() - timedelta(days=2),
        )
        unpublished_event = Event.objects.create(
            title="Unpublished Conference",
            website="https://example.com/unpublished-conference",
            is_active=False,
            start_date_time=timezone.now() + timedelta(days=20),
        )

        with self.captureOnCommitCallbacks(execute=True):
            self.speaker.events_spoken.add(past_event, unpublished_event)

        self.assertFalse(Notification.objects.filter(user=self.follower).exists())

    def test_publishing_event_after_speaker_assignment_notifies_followers(self):
        """Publishing an event after speaker assignment still sends an update."""
        event = Event.objects.create(
            title="Pending Conference",
            website="https://example.com/pending-conference",
            is_active=False,
            start_date_time=timezone.now() + timedelta(days=20),
        )
        self.speaker.events_spoken.add(event)

        with self.captureOnCommitCallbacks(execute=True):
            event.is_active = True
            event.save()

        notification = Notification.objects.get(user=self.follower)
        self.assertEqual(notification.link, event.get_absolute_url())

    def test_public_talk_notifies_followers_when_created(self):
        """A talk published at creation notifies only the speaker's followers."""
        with self.captureOnCommitCallbacks(execute=True):
            talk = self._create_talk(is_public=True)

        notification = Notification.objects.get(user=self.follower)
        self.assertIn(talk.title, notification.message)
        self.assertEqual(notification.link, f"/speakers/{self.speaker.slug}")
        self.assertEqual(Notification.objects.count(), 1)

    def test_private_talk_notifies_followers_only_when_published(self):
        """Private drafts stay private to followers until made public."""
        talk = self._create_talk(is_public=False)
        self.assertFalse(Notification.objects.exists())

        with self.captureOnCommitCallbacks(execute=True):
            talk.is_public = True
            talk.save()

        self.assertEqual(Notification.objects.filter(user=self.follower).count(), 1)

    def test_editing_public_talk_does_not_send_duplicate_notification(self):
        """Editing a talk that is already public does not notify again."""
        with self.captureOnCommitCallbacks(execute=True):
            talk = self._create_talk(is_public=True)
        talk.title = "Updated talk title"
        talk.save()
        self.assertEqual(Notification.objects.filter(user=self.follower).count(), 1)

    def test_notification_api_returns_link(self):
        """The notification endpoint exposes the target link to the frontend."""
        notification = Notification.objects.create(
            user=self.follower,
            message="A speaker update.",
            link="/speakers/example",
        )
        client = APIClient()
        client.force_authenticate(self.follower)

        response = client.get(reverse("speakers:notification_list"))

        self.assertEqual(response.status_code, 200)
        self.assertEqual(response.data["results"][0]["id"], str(notification.id))
        self.assertEqual(response.data["results"][0]["link"], "/speakers/example")

    def _create_talk(self, *, is_public):
        """Create a talk for the test speaker."""
        return Talks.objects.create(
            title="Reliable systems",
            description="A talk about reliable systems.",
            speaker=self.speaker,
            duration=30,
            category=TalkCategoryChoices.WEB,
            is_public=is_public,
        )
